import functools

def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        if '+' in core:
            core, _ = core.split('+', 1)
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        preids = pre.split('.') if pre is not None else None
        return (major, minor, patch, preids)

    def cmp_ids(a, b):
        a_num = a.isdigit()
        b_num = b.isdigit()
        if a_num and b_num:
            ai, bi = int(a), int(b)
            return (ai > bi) - (ai < bi)
        if a_num and not b_num:
            return -1
        if not a_num and b_num:
            return 1
        return (a > b) - (a < b)

    def compare(v1, v2):
        m1, mi1, p1, pre1 = parse(v1)
        m2, mi2, p2, pre2 = parse(v2)
        for x, y in ((m1, m2), (mi1, mi2), (p1, p2)):
            if x != y:
                return -1 if x < y else 1
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1
        for a, b in zip(pre1, pre2):
            c = cmp_ids(a, b)
            if c != 0:
                return c
        if len(pre1) != len(pre2):
            return -1 if len(pre1) < len(pre2) else 1
        return 0

    indexed = list(enumerate(versions))
    indexed.sort(key=functools.cmp_to_key(lambda a, b: compare(a[1], b[1]) or (a[0] - b[0])))
    return [v for _, v in indexed]

